#!/usr/bin/env python3
"""Installs the mb-project-docs skill, its three documents and its copy script, adds the agent rule to the global
AGENTS.md, and adds Step 2a to the close-out procedure. Every text change must match, or it is skipped and reported.
Nothing is committed here."""
import base64, os, re, stat, sys

C = os.environ.get("FINISH_C", "/mnt/c")
HOME = os.environ.get("FINISH_HOME", os.path.expanduser("~"))
FILES = {'SKILL.md': '', 'agents-from-reference.sh': '', 'project-docs-config.md': '', 'project-docs-reference.md': '', 'project-docs-explainer.md': ''}
problems = 0
def say(s): print("   " + s)
def w(path, name, overwrite):
    if os.path.exists(path) and not overwrite:
        say(f"exists, not overwritten: {path}"); return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path, "wb").write(base64.b64decode(FILES[name]))
    say(f"written: {path}")

print("1. The skill")
w(f"{HOME}/.config/opencode/skills/mb-project-docs/SKILL.md", "SKILL.md", True)
S = f"{C}/mybizz/mybizz-config-docs/mb-project-docs"
w(f"{S}/skill.md", "SKILL.md", True)
for n in ("project-docs-config.md", "project-docs-reference.md", "project-docs-explainer.md"):
    w(f"{S}/{n}", n, False)           # never overwritten: the commit hook gives each its permanent code
sh = f"{C}/mybizz/scripts/agents-from-reference.sh"
w(sh, "agents-from-reference.sh", True)
os.chmod(sh, os.stat(sh).st_mode | stat.S_IXUSR)

def patch(path, rx, rep, label, key, flags=re.S):
    global problems
    try: t = open(path, encoding="utf-8", newline="").read()
    except OSError:
        say(f"NOT FOUND   {path}"); problems += 1; return
    if key in t: return
    eol = "\r\n" if "\r\n" in t else "\n"
    new, n = re.subn(rx, lambda m: rep.replace("\n", eol), t, count=1, flags=flags)
    if n == 0:
        say(f"NOT CHANGED {os.path.basename(path)}: {label}"); problems += 1; return
    open(path, "w", encoding="utf-8", newline="").write(new)
    say(f"changed     {os.path.basename(path)}: {label}")

print("\n2. The agent rule (global AGENTS.md)")
RULE = """## Project documents

On entering a project (`makepdlf`, `mb-3-cs`, `mb4ecom`, `mb5pdlf` or `pdlf`), read these first, as required reading: the repository's `README.md`, its `{slug}-config.md`, its `AGENTS.md` (or `agents.md`) and its `{slug}-explainer.md`. In a code repository the config and the explainer are in `theme/docs`. They are kept current by `/mb-project-docs`, which is run at close-out.

---

## Grants — the permission slip"""
patch(f"{HOME}/.config/opencode/AGENTS.md", r"## Grants — the permission slip", RULE, "project documents rule", "## Project documents")

print("\n3. The close-out procedure")
CO = f"{C}/mybizz/mybizz-os-docs/operating-procedures/close-out-process.md"
STEP = """## Step 2a — agent: the project documents

When the session worked in one of the five projects (`makepdlf`, `mb-3-cs`, `mb4ecom`, `mb5pdlf`, `pdlf`), run `/mb-project-docs` for that project, up to its Step 6. Its presentation (the changes to config, explainer and README, the statements that were no longer true, and the changed lines of `AGENTS.md`) is part of the gate message. After the approval, carry out its Step 7: write the files and add its copy line to the terminal block, before `commit-all.sh`. When the session worked in no project, skip this step.

## Step 3 — agent: after the approval"""
patch(CO, r"## Step 3 — agent: after the approval", STEP, "Step 2a", "## Step 2a — agent: the project documents")
patch(CO, r"and the flagged\s+files\. Then STOP\.", "the flagged files, and the project documents (Step 2a). Then STOP.", "gate message", "and the project documents (Step 2a)")
patch(CO, r"The agent writes this block fully literal\.", "The agent writes this block fully literal. It also carries the copy line of Step 2a when the skill produced a reference file.", "terminal block", "copy line of Step 2a")

print("\n" + ("Some changes did not match (listed above). Paste this screen to Claude." if problems else "All done."))
sys.exit(1 if problems else 0)
